"""Track T4. Classify, search, patch, retry. At most 3 attempts per step."""

from __future__ import annotations

import re
import sys
from typing import Callable

import httpx
import neatlogs

from firstrun import budget as budget_mod
from firstrun import classify as classify_mod
from firstrun import config, llm, precedents
from firstrun.budget import BudgetExceeded
from firstrun.models import (
    Budget,
    Classification,
    FailureClass,
    GaveUp,
    Patch,
    RunState,
    Step,
    StepResult,
)

CONFIDENT = 0.7        # below this, ask the human once
STORE_CONFIDENT = 0.9  # at or above this, a model answer is stored as a precedent

_LETTERS = {"d": FailureClass.DOCS_BUG, "e": FailureClass.ENVIRONMENT,
            "p": FailureClass.PRODUCT_BUG, "s": FailureClass.NEEDS_SECRET}

Asker = Callable[[str], str]


def _error_line(error_text: str) -> str:
    lines = [ln.strip() for ln in error_text.splitlines() if ln.strip()]
    return (lines[-1] if lines else "no output")[:200]


def _terminal_asker(question: str) -> str | None:
    if not sys.stdin or not sys.stdin.isatty():
        return None
    return input(question + " ")


def _parse_answer(answer: str | None) -> FailureClass | None:
    if not answer:
        return None
    a = answer.strip().lower()
    for cls in FailureClass:
        if a == cls.value or a == cls.value.replace("_", " "):
            return cls
    return _LETTERS.get(a[:1]) if len(a) == 1 else None


def _resolve(error_text: str, command: str, asker: Asker | None, step_id: int | None) -> Classification:
    sig = classify_mod.signature(error_text)
    known = precedents.lookup(sig)
    if known is not None:
        neatlogs.log("precedent reused", signature=sig, failure_class=known.value)
        return Classification(probabilities={c: (1.0 if c == known else 0.0) for c in FailureClass},
                              source="precedent")
    cls = classify_mod.classify(error_text, command)
    if cls.confidence >= CONFIDENT:
        if cls.confidence >= STORE_CONFIDENT:
            precedents.store(sig, cls.top, example=error_text)
        return cls
    where = f"Step {step_id}" if step_id is not None else "Step"
    question = (f"{where} failed: {_error_line(error_text)}. Is this a docs bug, an environment issue, "
                "a product bug, or a missing secret? [d/e/p/s]")
    ask = asker or _terminal_asker
    answer = _parse_answer(ask(question))
    if answer is None:
        neatlogs.log("no human answer, using the top class", level="warning",
                     failure_class=cls.top.value, confidence=cls.confidence)
        return cls
    precedents.store(sig, answer, example=error_text)
    return Classification(probabilities={c: (1.0 if c == answer else 0.0) for c in FailureClass},
                          source="human")


def resolve_class(error_text: str, command: str, asker: Asker | None = None,
                  step_id: int | None = None) -> tuple[FailureClass, str]:
    """Precedent first, then the classifier, then ask the human once if unsure."""
    cls = _resolve(error_text, command, asker, step_id)
    return cls.top, cls.source


# --- environment fixes -------------------------------------------------------

# (error pattern, apt packages). A small known table so most fixes need no model.
_ENV_FIXES: list[tuple[re.Pattern, str]] = [
    (re.compile(r"\bcurl: (?:command )?not found|curl: not found|\bcurl\b.*not found", re.I), "curl"),
    (re.compile(r"\bgit: (?:command )?not found|\bgit\b.*not found|No such file or directory: 'git'", re.I), "git"),
    (re.compile(r"\bwget: (?:command )?not found|\bwget\b.*not found", re.I), "wget"),
    (re.compile(r"\b(?:gcc|cc|g\+\+|make): (?:command )?not found|command 'gcc' failed|unable to execute 'gcc'|"
                r"failed to build wheel|python\.h: no such file", re.I), "build-essential"),
    (re.compile(r"\b(?:node|npm|npx): (?:command )?not found", re.I), "nodejs npm"),
]


def _env_packages(error_text: str) -> str | None:
    for pattern, pkgs in _ENV_FIXES:
        if pattern.search(error_text):
            return pkgs
    return None


# --- docs bug hints ----------------------------------------------------------

_PIP_MISSING = re.compile(r"No matching distribution found for ([A-Za-z0-9_.\-]+)(?:\[[^\]]*\])?\s*(?:==|>=|<=|~=|>|<)?\s*([\w.]*)")


def _pypi_hint(error_text: str) -> str:
    """Cheap first hint with no model: valid versions of the package pip could not find."""
    m = _PIP_MISSING.search(error_text)
    if not m:
        return ""
    name = m.group(1)
    try:
        r = httpx.get(f"https://pypi.org/pypi/{name}/json", timeout=10)
        if r.status_code == 404:
            return f"PyPI hint: no package named {name} exists on PyPI. It may have been renamed."
        r.raise_for_status()
        releases = [v for v, files in r.json().get("releases", {}).items() if files and not all(f.get("yanked") for f in files)]
        try:
            from packaging.version import Version
            releases.sort(key=Version)
        except Exception:
            pass
        latest = r.json().get("info", {}).get("version", "")
        return f"PyPI hint: {name} has these versions (newest last): {', '.join(releases[-15:])}. Latest is {latest}."
    except Exception:
        return ""


def _read_allowlist() -> dict[str, str]:
    """KEY=VALUE lines. Values are never logged or returned to callers outside this module."""
    out: dict[str, str] = {}
    try:
        for line in config.SECRETS_ALLOWLIST.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                out[k.strip()] = v.strip()
    except OSError:
        pass
    return out


def _add_usage(state: RunState, usage: dict) -> None:
    state.usage.tool_calls += int(usage.get("tool_calls", 0))
    state.usage.input_tokens += int(usage.get("input_tokens", 0))
    state.usage.output_tokens += int(usage.get("output_tokens", 0))
    state.usage.cost_usd += float(usage.get("cost_usd", 0.0))


def _error_text(result: StepResult) -> str:
    text = (result.stderr or "") + ("\n" if result.stderr and result.stdout else "") + (result.stdout or "")
    if result.timed_out:
        text += "\n(command timed out)"
    return text[-3000:]


def _ask_fix(prompt: str, tools: tuple[str, ...], max_turns: int, state: RunState, bud: Budget,
             step: Step, old_command: str, cls: FailureClass, tried: list[str]) -> Patch | GaveUp:
    """One budgeted Claude call that must return {new_command, reason, source}."""
    try:
        budget_mod.check(state, bud, step.id)
    except BudgetExceeded as exc:
        return GaveUp(step_id=step.id, reason=str(exc), failure_class=cls)
    try:
        data, usage = llm.ask_json(prompt, system="You fix failing shell commands from developer quickstart guides.",
                                   tools=tools, max_turns=max_turns)
    except Exception as exc:  # noqa: BLE001
        return GaveUp(step_id=step.id, reason=f"model call failed: {type(exc).__name__}", failure_class=cls)
    _add_usage(state, usage)
    new = str(data.get("new_command") or "").strip()
    if not new or new == old_command.strip() or new in tried:
        return GaveUp(step_id=step.id, reason="no new fix found: the model repeated an earlier command",
                      failure_class=cls)
    return Patch(step_id=step.id, old_command=old_command, new_command=new,
                 reason=str(data.get("reason") or "")[:300], failure_class=cls,
                 source=str(data.get("source") or ""))


def recover(step: Step, result: StepResult, state: RunState, docs_markdown: str = "",
            asker: Asker | None = None, budget: Budget | None = None) -> Patch | GaveUp:
    """AGENT span `recover.<id>`. Returns a Patch to retry with, or GaveUp."""
    bud = budget or Budget()
    with neatlogs.trace(f"recover.{step.id}", kind="AGENT"):
        return _recover(step, result, state, docs_markdown, asker, bud)


def _recover(step: Step, result: StepResult, state: RunState, docs_markdown: str,
             asker: Asker | None, bud: Budget) -> Patch | GaveUp:
    error_text = _error_text(result)
    old_command = result.command or step.command
    attempts = state.attempts.get(step.id, 0)
    neatlogs.log("retry {attempt} after {error}", level="warning",
                 attempt=max(attempts, 1), error=_error_line(error_text))
    try:
        budget_mod.check(state, bud, step.id)
    except BudgetExceeded as exc:
        return GaveUp(step_id=step.id, reason=str(exc))

    classify_mod.LAST_USAGE.clear()
    cls = _resolve(error_text, old_command, asker, step.id)
    if classify_mod.LAST_USAGE:  # the classifier fell back to Claude
        _add_usage(state, classify_mod.LAST_USAGE)
        classify_mod.LAST_USAGE.clear()
    state.classifications[step.id] = cls
    top = cls.top

    tried = [p.new_command for p in state.patches if p.step_id == step.id]

    if top == FailureClass.PRODUCT_BUG:
        return GaveUp(step_id=step.id, reason=f"product bug: {_error_line(error_text)}", failure_class=top)

    if top == FailureClass.NEEDS_SECRET:
        allow = _read_allowlist()
        haystack = f"{error_text}\n{old_command}\n{docs_markdown}"
        name = next((k for k in allow if re.search(rf"\b{re.escape(k)}\b", haystack)), None)
        if name is None:
            return GaveUp(step_id=step.id, reason="needs a secret that is not in the allowlist: "
                          + _error_line(error_text), failure_class=top)
        # The executor injects the value into the container. The name goes in `source`.
        return Patch(step_id=step.id, old_command=old_command, new_command=old_command,
                     reason="secret supplied from allowlist", failure_class=top, source=name)

    if top == FailureClass.ENVIRONMENT:
        pkgs = _env_packages(error_text)
        if pkgs:
            new = f"apt-get update -qq && apt-get install -y -qq {pkgs} && {old_command}"
            if new not in tried:
                return Patch(step_id=step.id, old_command=old_command, new_command=new,
                             reason=f"the base image lacks {pkgs}; install it first", failure_class=top,
                             source="apt")
        prompt = (f"A command failed in a clean python:3.11-slim container because of the environment.\n"
                  f"Command: {old_command}\nError tail:\n{error_text}\n"
                  f"Earlier fixes that did not work: {tried or 'none'}\n"
                  'Return JSON {"new_command": "...", "reason": "...", "source": "..."}. '
                  "new_command must run the original command after any container fix, as one shell line.")
        return _ask_fix(prompt, (), 1, state, bud, step, old_command, top, tried)

    # docs_bug
    hint = _pypi_hint(error_text)
    prompt = (f"A step from a developer quickstart failed in a clean Docker container (python:3.11-slim).\n"
              f"Step intent: {step.intent}\nCommand: {old_command}\nError tail:\n{error_text}\n"
              f"{hint}\n"
              f"Earlier patches for this step that also failed: {tried or 'none'}\n"
              f"Docs excerpt:\n{docs_markdown[:3000]}\n\n"
              "Find the current, correct command with WebSearch and WebFetch. Prefer the tool's own docs, "
              "its registry page or its issue tracker. "
              'Return JSON {"new_command": "...", "reason": "...", "source": "<url you used>"}.')
    return _ask_fix(prompt, ("WebSearch", "WebFetch"), 6, state, bud, step, old_command, top, tried)
"""Track T4. Classifies a failed step's error output into the four failure classes."""

from __future__ import annotations

import hashlib
import os
import re

import httpx
import neatlogs

from firstrun import config
from firstrun.models import Classification, FailureClass

JEV_URL = "https://api.typesafe.ai/v1/systemone"
JEV_MODEL = "jev-latest"

# Usage of the last Claude fallback call. recovery.py adds it to the run, then clears it.
LAST_USAGE: dict = {}

_TELLING = re.compile(
    r"error|exception|not found|failed|denied|no matching|cannot|can't|unable|unauthorized|refused|timed out|invalid|unknown|unrecognized",
    re.I,
)


def signature(error_text: str) -> str:
    """Short stable signature of an error: strips paths, numbers and hashes."""
    lines = [ln.strip() for ln in error_text.splitlines() if ln.strip()]
    telling = [ln for ln in lines if _TELLING.search(ln)]
    line = (telling or lines or [""])[-1]  # tools print the real error last
    line = line.lower()
    line = re.sub(r"[\"'`]", "", line)
    line = re.sub(r"(?:[a-z]:)?[\\/][^\s:,;)]*", "<path>", line)
    line = re.sub(r"\b(?:0x)?[0-9a-f]{7,}\b", "<hex>", line)
    line = re.sub(r"\d+(?:\.\d+)*", "<n>", line)
    line = re.sub(r"\s+", " ", line).strip()
    digest = hashlib.sha1(line.encode("utf-8")).hexdigest()[:12]
    prefix = re.sub(r"[^a-z]+", "-", line).strip("-")[:30].strip("-")
    return f"{prefix}-{digest}" if prefix else digest


def _normalize(raw: dict) -> dict[FailureClass, float]:
    probs = {c: max(0.0, float(raw.get(c.value, 0.0) or 0.0)) for c in FailureClass}
    total = sum(probs.values())
    if total <= 0:
        raise ValueError("no probabilities")
    return {c: p / total for c, p in probs.items()}


_CRITERIA = {
    "docs_bug": "The docs are wrong: package renamed, flag removed, wrong import path, or a version that moved.",
    "environment": "The sandbox is missing something: a system package in the base image, or a network timeout.",
    "product_bug": "The tool itself crashes on a correct command.",
    "needs_secret": "The step asks for an API key, token or login that the container lacks.",
}


def _jev(error_text: str, command: str) -> dict[FailureClass, float] | None:
    """Ask Jev one Choice question. Returns None on any failure."""
    config.load_env()
    key = os.environ.get("TYPESAFE_API_KEY")
    if not key:
        return None
    body = {
        "model": JEV_MODEL,
        "state": {"command": command, "error_output": error_text[-3000:]},
        "questions": {"failure_class": {
            "type": "choice",
            "instructions": "A shell command from a quickstart guide failed in a clean container. Which kind of failure is it?",
            "criteria": _CRITERIA,
        }},
    }
    try:
        r = httpx.post(JEV_URL, json=body, headers={"Authorization": f"Bearer {key}"}, timeout=30)
        r.raise_for_status()
        answer = r.json()["answers"]["failure_class"]
        return _normalize(answer["probabilities"])
    except Exception:  # any failure sends us to the next fallback
        return None


def _claude(error_text: str, command: str) -> dict[FailureClass, float] | None:
    from firstrun import llm

    prompt = (
        "A shell command from a developer quickstart failed in a clean Docker container.\n"
        f"Command: {command}\nError output:\n{error_text[-3000:]}\n\n"
        "Classes: " + "; ".join(f"{k}: {v}" for k, v in _CRITERIA.items()) + "\n"
        'Return JSON: {"docs_bug": p, "environment": p, "product_bug": p, "needs_secret": p} '
        "with probabilities that sum to 1."
    )
    try:
        data, usage = llm.ask_json(prompt, system="You classify failures.", max_turns=1)
        LAST_USAGE.clear()
        LAST_USAGE.update(usage)
        return _normalize(data)
    except Exception:
        return None


# Ordered: the first matching group wins.
_HEURISTICS: list[tuple[FailureClass, re.Pattern]] = [
    (FailureClass.NEEDS_SECRET, re.compile(
        r"api[_ -]?key|auth(?:entication|orization)? (?:required|failed|error)|unauthorized|\b401\b|"
        r"not logged in|please log ?in|missing (?:token|credentials)|invalid (?:token|credentials)|(?-i:[A-Z][A-Z0-9_]+_(?:KEY|TOKEN|SECRET)\b)", re.I)),
    (FailureClass.ENVIRONMENT, re.compile(
        r"command not found|: not found|no such file or directory: '?(?:gcc|cc|make|git|curl)|"
        r"could not resolve host|temporary failure in name resolution|timed out|connection (?:refused|reset)|"
        r"failed to build wheel|error: command '(?:gcc|cc)' failed|python\.h|unable to locate package", re.I)),
    (FailureClass.DOCS_BUG, re.compile(
        r"no matching distribution|could not find a version|modulenotfounderror|importerror|cannot import name|"
        r"unrecognized arguments|no such option|unknown (?:option|command|flag)|unexpected keyword|"
        r"has no attribute|is not a known|deprecated|removed|404|no such command|invalid choice", re.I)),
    (FailureClass.PRODUCT_BUG, re.compile(
        r"segmentation fault|internal (?:server )?error|panic:|assertionerror|unhandled exception|core dumped|\b500\b", re.I)),
]


def _heuristic(error_text: str, command: str = "") -> dict[FailureClass, float]:
    for cls, pattern in _HEURISTICS:
        if pattern.search(error_text):
            rest = 0.2 / 3
            return {c: (0.8 if c == cls else rest) for c in FailureClass}
    return {c: 0.25 for c in FailureClass}  # no signal: low confidence, so we ask


@neatlogs.span(kind="TOOL", name="classify_failure")
def classify(error_text: str, command: str = "") -> Classification:
    """TOOL span `classify_failure`. Jev first, Claude as fallback. Returns four probabilities."""
    probs = _jev(error_text, command)
    if probs is not None:
        return Classification(probabilities=probs, source="jev")
    neatlogs.log("jev unavailable, falling back to claude", level="warning")
    probs = _claude(error_text, command)
    if probs is not None:
        return Classification(probabilities=probs, source="claude")
    neatlogs.log("claude unavailable, falling back to heuristics", level="warning")
    return Classification(probabilities=_heuristic(error_text, command), source="heuristic")
"""Track T5. Model-free re-run of the patched runbook in a brand-new container.

This file must never import the planner, recovery or llm modules. A test enforces it.
"""

from __future__ import annotations

import uuid
from typing import Any, Callable

import neatlogs

from firstrun.models import Patch, Runbook, RunStatus, StepResult


def apply_patches(runbook: Runbook, patches: list[Patch]) -> Runbook:
    """Return a deep copy with each patched step's command replaced. The last patch per step wins."""
    patched = runbook.model_copy(deep=True)
    latest: dict[int, Patch] = {}
    for patch in patches:
        latest[patch.step_id] = patch
    for step in patched.steps:
        if step.id in latest:
            step.command = latest[step.id].new_command
    return patched


def _default_factory(image: str, name: str):
    from firstrun.sandbox import Container

    return Container(image=image, name=name)


def _default_run_step(container, step) -> StepResult:
    from firstrun.executor import run_step

    return run_step(container, step)


def _run(
    runbook: Runbook,
    patches: list[Patch],
    container_factory: Callable[[str, str], Any] | None,
    run_step: Callable[[Any, Any], StepResult] | None,
) -> tuple[RunStatus, dict]:
    factory = container_factory or _default_factory
    runner = run_step or _default_run_step
    patched = apply_patches(runbook, patches)
    name = f"firstrun-verify-{uuid.uuid4().hex[:8]}"
    details: dict = {"container": name, "image": patched.image, "steps": [], "failed_step": None, "reason": ""}

    with neatlogs.trace("verify", kind="GUARDRAIL") as span:
        try:
            with factory(patched.image, name) as container:
                for step in patched.steps:
                    result = runner(container, step)
                    details["steps"].append(
                        {
                            "step_id": step.id,
                            "command": step.command,
                            "passed": bool(result.passed),
                            "duration_s": result.duration_s,
                        }
                    )
                    if not result.passed:
                        details["failed_step"] = step.id
                        details["reason"] = f"step {step.id} failed (exit {result.exit_code})"
                        neatlogs.log("verify failed at step {id}", id=step.id, command=step.command, exit_code=result.exit_code)
                        break
        except Exception as exc:  # a broken container counts as unverified
            details["reason"] = f"verification error: {exc}"
            neatlogs.log("verify error: {err}", err=str(exc))

        passed = not details["reason"] and len(details["steps"]) == len(patched.steps)
        if passed:
            details["reason"] = f"all {len(patched.steps)} steps passed in a fresh container, no model calls"
        span.set_attribute("neatlogs.guardrail.passed", passed)
        span.set_attribute("neatlogs.guardrail.reason", details["reason"])

    return (RunStatus.VERIFIED if passed else RunStatus.UNVERIFIED), details


def verify(
    runbook: Runbook,
    patches: list[Patch],
    container_factory: Callable[[str, str], Any] | None = None,
    run_step: Callable[[Any, Any], StepResult] | None = None,
    out: dict | None = None,
) -> RunStatus:
    """GUARDRAIL span `verify`. Returns RunStatus.VERIFIED or RunStatus.UNVERIFIED. Never calls a model.

    `container_factory(image, name)` returns a context manager. `out`, when given, receives the details.
    """
    status, details = _run(runbook, patches, container_factory, run_step)
    if out is not None:
        out.update(details)
        out["status"] = status.value
    return status


def verify_details(
    runbook: Runbook,
    patches: list[Patch],
    container_factory: Callable[[str, str], Any] | None = None,
    run_step: Callable[[Any, Any], StepResult] | None = None,
) -> dict:
    """Same run as verify(), returned as a dict: status, per-step pass/fail and duration, reason."""
    out: dict = {}
    verify(runbook, patches, container_factory, run_step, out)
    return out
"""Track T5. The docs diff and the draft PR body."""

from __future__ import annotations

import difflib
import re
from pathlib import Path

from firstrun.models import FailureClass, Patch, Runbook, RunState, RunStatus

_PROMPT = re.compile(r"^\s*(?:\$|>)\s+")


def _replace_line(lines: list[str], old: str, new: str) -> bool:
    """Replace `old` with `new` in the first line that holds it. Retry without a shell prompt."""
    for i, line in enumerate(lines):
        if old in line:
            lines[i] = line.replace(old, new, 1)
            return True
    bare = _PROMPT.sub("", old).strip()
    if not bare:
        return False
    for i, line in enumerate(lines):
        body = line.rstrip("\r\n")
        if _PROMPT.sub("", body).strip() == bare:
            prompt = _PROMPT.match(body)
            ending = line[len(body):]
            lead = body[: len(body) - len(body.lstrip())]
            lines[i] = (prompt.group(0) if prompt else lead) + _PROMPT.sub("", new).strip() + ending
            return True
    return False


def make_diff(docs_md: str, patches: list[Patch], path: str = "quickstart.md") -> str:
    """Unified diff of the docs markdown with each patched command replaced."""
    docs_patches = [p for p in patches if p.failure_class != FailureClass.ENVIRONMENT]
    env_patches = [p for p in patches if p.failure_class == FailureClass.ENVIRONMENT]
    if not docs_patches:
        return ""

    text = docs_md
    unplaced: list[Patch] = []
    for p in docs_patches:
        if "\n" in p.old_command and p.old_command in text:
            text = text.replace(p.old_command, p.new_command, 1)
            continue
        lines = text.splitlines(keepends=True)
        if _replace_line(lines, p.old_command, p.new_command):
            text = "".join(lines)
        else:
            unplaced.append(p)

    body = "".join(
        difflib.unified_diff(
            docs_md.splitlines(keepends=True),
            text.splitlines(keepends=True),
            fromfile=f"a/{path}",
            tofile=f"b/{path}",
        )
    )
    if not body and not unplaced:
        return ""
    out = "".join(f"# step {p.step_id} could not be located in the docs: {p.old_command}\n" for p in unplaced)
    out += body
    if body and not body.endswith("\n"):
        out += "\n"
    if env_patches:
        out += "# Environment fixes, not part of the docs change:\n"
        for p in env_patches:
            out += f"# step {p.step_id}: {p.old_command} -> {p.new_command} ({p.reason})\n"
    return out


def _error_line(state: RunState, step_id: int) -> str:
    for r in state.results:
        if r.step_id == step_id and not r.passed:
            text = (r.stderr or r.stdout).strip().splitlines()
            if text:
                return text[-1].strip()
    return ""


def make_pr_body(state: RunState, patches: list[Patch], trace_url: str = "", checkpoint_url: str = "") -> str:
    docs_patches = [p for p in patches if p.failure_class != FailureClass.ENVIRONMENT] or patches
    first = docs_patches[0] if docs_patches else None
    verified = state.status == RunStatus.VERIFIED
    n_steps = len({r.step_id for r in state.results}) or len(state.step_status)

    lines = ["Fix a broken command in the quickstart", ""]
    lines += ["Hi, thanks for maintaining this project. I found a step in the quickstart that fails in a clean container.", ""]
    if first:
        lines += ["## What broke", "", f"- Step: {first.step_id}", f"- Command: `{first.old_command}`"]
        err = _error_line(state, first.step_id)
        if err:
            lines.append(f"- Error: `{err}`")
        lines += ["", "## The fix", ""]
        for p in docs_patches:
            lines.append(f"- Step {p.step_id}: `{p.old_command}` becomes `{p.new_command}`. {p.reason}")
            if p.source:
                lines.append(f"  Source: {p.source}")
        lines.append("")
    lines += ["## Proof", ""]
    if verified:
        count = f"all {n_steps} steps" if n_steps else "every step"
        lines.append(
            f"Verified: a fresh python:3.11-slim container ran {count} with the patch, no model calls during verification."
        )
    else:
        lines.append("Not verified. The patched runbook did not pass in a fresh container, so treat this fix as a suggestion.")
    if state.time_to_first_success_s is not None:
        lines.append(f"Time to first success: {state.time_to_first_success_s:.0f} seconds.")
    links = []
    if trace_url:
        links.append(f"- Trace: {trace_url}")
    if checkpoint_url:
        links.append(f"- Entire checkpoint: {checkpoint_url}")
    if links:
        lines += ["", "## Links", ""] + links
    lines += ["", "Found by FirstRun, an agent that runs quickstarts in a clean container.", ""]
    return "\n".join(lines)


def _docs_path(runbook: Runbook) -> str:
    name = runbook.source_url.rstrip("/").rsplit("/", 1)[-1]
    return name if name.lower().endswith((".md", ".mdx")) else "quickstart.md"


def write_outputs(run_dir: Path, state: RunState, runbook: Runbook, trace_url: str = "") -> list[Path]:
    """Write patch.diff and pr_body.md only for a verified docs patch."""
    if state.status != RunStatus.VERIFIED:
        return []
    diff = make_diff(runbook.docs_markdown, state.patches, _docs_path(runbook))
    if not diff:
        return []
    run_dir = Path(run_dir)
    run_dir.mkdir(parents=True, exist_ok=True)
    diff_path = run_dir / "patch.diff"
    body_path = run_dir / "pr_body.md"
    diff_path.write_text(diff, encoding="utf-8")
    body_path.write_text(make_pr_body(state, state.patches, trace_url), encoding="utf-8")
    return [diff_path, body_path]
